function epochUtc(y, m, d, hour) {
    var y2 = y;
    if (m <= 2) {
        y2 = y2 - 1;
    }
    var era = Math.floor(y2 / 400);
    var yoe = y2 - era * 400;
    var shift = 9;
    if (m > 2) {
        shift = -3;
    }
    var doy = Math.floor((153 * (m + shift) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    var days = era * 146097 + doe - 719468;
    return (days * 86400 + hour * 3600) * 1000;
}

function add(a, b) {
    return (a + b) * 1;
}

function sub(a, b) {
    return (a - b) * 1;
}

if (TotalSteamConsumption.size < 2) {
    return {
        "SteamConsumptionDaily": 0.0
    };
}

var currTs = 0;
var curr = null;
foreach(reading: TotalSteamConsumption.values) {
    if (reading.value != null && !isNaN(reading.value) && reading.value > 0) {
        currTs = reading.ts;
        curr = reading.value;
    }
}

if (curr == null) {
    return {
        "SteamConsumptionDaily": 0.0
    };
}

var stamp = new Date(currTs);
var year = stamp.getUTCFullYear();
var t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
var dowMarch = (year + Math.floor(year / 4) - Math.floor(year / 100) + Math.floor(year / 400) + t[2] + 31) % 7;
var dowOct = (year + Math.floor(year / 4) - Math.floor(year / 100) + Math.floor(year / 400) + t[9] + 31) % 7;
var dstStart = epochUtc(year, 3, 31 - dowMarch, 1);
var dstEnd = epochUtc(year, 10, 31 - dowOct, 1);

var offsetMs = 3600000;
if (currTs >= dstStart && currTs < dstEnd) {
    offsetMs = 7200000;
}

var readingLocal = add(currTs, offsetMs);
var readingDayMod = readingLocal % 86400000;
var readingMidnight = sub(readingLocal, readingDayMod);

var nowTs = new Date().getTime();
var nowStamp = new Date(nowTs);
var nowYear = nowStamp.getUTCFullYear();
var nowDowMarch = (nowYear + Math.floor(nowYear / 4) - Math.floor(nowYear / 100) + Math.floor(nowYear / 400) + t[2] + 31) % 7;
var nowDowOct = (nowYear + Math.floor(nowYear / 4) - Math.floor(nowYear / 100) + Math.floor(nowYear / 400) + t[9] + 31) % 7;
var nowDstStart = epochUtc(nowYear, 3, 31 - nowDowMarch, 1);
var nowDstEnd = epochUtc(nowYear, 10, 31 - nowDowOct, 1);

var nowOffset = 3600000;
if (nowTs >= nowDstStart && nowTs < nowDstEnd) {
    nowOffset = 7200000;
}

var nowLocal = add(nowTs, nowOffset);
var nowDayMod = nowLocal % 86400000;
var nowMidnight = sub(nowLocal, nowDayMod);

if (readingMidnight < nowMidnight) {
    return {
        "SteamConsumptionDaily": 0.0
    };
}

var dayStart = sub(readingMidnight, offsetMs);
var prev = null;
var firstToday = null;
foreach(sample: TotalSteamConsumption.values) {
    if (sample.value != null && !isNaN(sample.value) && sample.value > 0) {
        if (sample.ts <= dayStart) {
            prev = sample.value;
        }
        if (sample.ts > dayStart && firstToday == null) {
            firstToday = sample.value;
        }
    }
}

if (prev == null) {
    prev = firstToday;
}
if (prev == null) {
    return {
        "SteamConsumptionDaily": 0.0
    };
}

var delta = 0.0;
if (curr < prev) {
    delta = curr;
} else {
    delta = sub(curr, prev);
}

return {
    "SteamConsumptionDaily": delta
};

if (steam_readings.size < 2) {
    return { "SteamConsumptionRate": 0.0 };
}

var p = null;
var c = null;
var readingValue = 0.0;

foreach (reading : steam_readings.values) {
    readingValue = reading.value;
    if (!isNaN(readingValue) && readingValue != 0) {
        p = c;
        c = reading;
    }
}

if (p == null || c == null) {
    return { "SteamConsumptionRate": 0.0 };
}

var prev = p.value;
var curr = c.value;
if (isNaN(prev) || isNaN(curr)) {
    return { "SteamConsumptionRate": 0.0 };
}
var dtHours = (c.ts - p.ts) / 3600000.0;
if (dtHours <= 0) {
    return { "SteamConsumptionRate": 0.0 };
}
var delta = 0.0;
if (curr < prev) {
    delta = (curr >= 0 ? curr : 0.0);
} else {
    delta = curr - prev;
}
return { "SteamConsumptionRate": toFixed(delta / dtHours, 4) };
